def bindings(net, export=False):
    rows = []
    for e in net['edges']:
        ids = [x['id'] for x in e.get('working_bindings', [])] or ['DENT-UNC-PROPAGATION']
        rows.append({'id': 'DENT-CONSTRAINT-R3-' + e['id'], 'type': 'CLAIM', 'status': 'OPEN', 'claim_type': 'capability', 'review_state': 'PENDING_INDEPENDENT_REVIEW', 'claim': e['constraint'], 'annotation_for': ids[0], 'working_ids': ids, 'constraint_status': e['status'], 'constraint_id': e['id'], 'availability_status': e.get('blocker_status', e.get('gap', {}).get('kind')), 'source_contract': e, 'gap': e.get('gap'), 'measurement_obligation': e.get('measurement_obligation'), 'depends_on': [], 'no_scientific_admission': True, 'evidence': ['results/PROOF_LANE_CONSTRAINT_NET_R3/CONSTRAINT_NET_DENTAL_R3.json'], 'net_sha256': sha(HERE / 'CONSTRAINT_NET_DENTAL_R3.json'), 'proposal_role': 'quantity_context_not_native_dependency'})
    payload = ''.join((json.dumps(r, ensure_ascii=False, separators=(',', ':'), allow_nan=False) + '\n' for r in rows))
    name = 'constraint_net_dental_r3_20261003.jsonl'
    (HERE / name).write_text(payload)
    if export:
        dest = DENT / 'notes/expansion' / name
        if dest.exists() and dest.read_text() != payload:
            raise RuntimeError('EXISTING_BINDINGS_DIFFER; no overwrite')
        if not dest.exists():
            dest.write_text(payload)
        dump('BINDINGS_RECEIPT.json', {'path': str(dest), 'sha256': sha(dest), 'rows': len(rows), 'review_state': 'PENDING_INDEPENDENT_REVIEW', 'source_graphs_modified': False})
    return {'relative_path': name, 'sha256': sha(HERE / name), 'rows': len(rows), 'requested_expansion_path': 'notes/expansion/' + name}

